import RNA
import random, sys

target='((..(..((....))..(((.(..(.(((...)))..)..)..)))..(..(....)..).(..(....)..).....((....))..)..))..((..(..((....))..(((.(..(.(((...)))..)..)..)))..(..(....)..).(..(....)..).....((....))..)..))..((..(..((....))..(((.(..(.(((...)))..)..)..)))..(..(....)..).(..(....)..).....((....))..)..))..((..(..((....))..(((.(..(.(((...)))..)..)..)))..(..(....)..).(..(....)..).....((....))..)..))'
n=len(target)
stack=[]; pairs={}
for i,c in enumerate(target):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j

ts_set=set()
st=[]
for i,c in enumerate(target):
    if c=='(':
        st.append(i)
    elif c==')':
        j=st.pop(); ts_set.add((j,i)); ts_set.add((i,j))

def fs_set(ss):
    st=[]; s=set()
    for i,c in enumerate(ss):
        if c=='(':
            st.append(i)
        elif c==')':
            j=st.pop(); s.add((j,i)); s.add((i,j))
    return s

def score(seq):
    fc=RNA.fold_compound(seq)
    ss,_=fc.mfe()
    fs=fs_set(ss)
    return len(ts_set-fs)+len(fs-ts_set), ss

def make_initial():
    seq=['A']*n
    for i in range(n):
        if i in pairs and i<pairs[i]:
            j=pairs[i]; seq[i]='G'; seq[j]='C'
    return ''.join(seq)

random.seed(7)
seq=make_initial()
best=score(seq); best_seq=seq
sys.stdout.write('init %d\n'%best[0]); sys.stdout.flush()

for it in range(800):
    sc,ss=best
    if sc==0: break
    fs=fs_set(ss)
    missing=ts_set-fs; spurious=fs-ts_set
    p=list(seq)
    r=random.random()
    if missing and r<0.6:
        i,j=random.choice(list(missing))
        ch=random.choice([('G','C'),('C','G')])
        p[i]=ch[0]; p[j]=ch[1]
    elif spurious and r<0.9:
        i,j=random.choice(list(spurious))
        end=i if random.random()<0.5 else j
        p[end]=random.choice(['A','U'])
    else:
        i=random.randint(0,n-1); p[i]=random.choice(['A','C','G','U'])
    cand=''.join(p)
    s2,_=score(cand)
    if s2<best[0] or (s2==best[0] and random.random()<0.3):
        best=(s2,score(cand)[1]); best_seq=cand; seq=cand
    if it%100==0:
        sys.stdout.write('it %d best %d\n'%(it,best[0])); sys.stdout.flush()
sys.stdout.write('final %d\n'%best[0])
sys.stdout.write('SEQ '+best_seq+'\n')
